 async function refreshFX(quiet=false){const currencies=[...new Set([...state.assets.map(a=>a.currency),...Object.keys(stats.cash)])].filter(c=>c!=='PLN');if(!currencies.length)throw new Error('Dodaj najpierw instrument lub operację w walucie obcej.');const next=clone(),errors=[];for(const c of currencies){try{let r;if(storageMode==='server')r=await api('fx&currency='+encodeURIComponent(c));else{const resp=await fetch(`https://api.nbp.pl/api/exchangerates/rates/a/${encodeURIComponent(c)}/last/93/?format=json`,{signal:AbortSignal.timeout(15000)});if(!resp.ok)throw new Error('NBP nie udostępnia tej waluty w tabeli A. Ustaw kurs ręcznie.');const obj=await resp.json(),last=obj.rates.at(-1);r={rate:last.mid,date:last.effectiveDate,source:'NBP · tabela A',history:obj.rates.map(p=>({date:p.effectiveDate,rate:p.mid}))};}next.fx[c]=H.fx(next.fx[c],r);}catch(e){errors.push(c+': '+e.message);}}await commit(next);if(errors.length)toast('Kursy niepełne: '+errors.join('; '));else if(!quiet)toast('Zaktualizowano kursy NBP.');}
 async function refreshQuotes(id){if(demo)throw new Error('Otwórz swój portfel, aby pobrać aktualne dane. Demo ma wyłącznie przykładowe ceny.');if(storageMode!=='server')throw new Error('Automatyczne notowania wymagają części PHP. Możesz wpisać cenę ręcznie lub zaimportować CSV.');const assets=id?state.assets.filter(a=>a.id===id):state.assets.filter(a=>a.providerSymbol);if(!assets.length)throw new Error('Dodaj symbol Yahoo Finance w edycji instrumentu.');const next=clone(),errors=[];for(const a of assets){try{if(!a.providerSymbol)throw new Error('Brak symbolu źródła.');const q=await api('quote&symbol='+encodeURIComponent(a.providerSymbol));if(q.currency!==a.currency)throw new Error(`Źródło podaje ${q.currency}, instrument ma ${a.currency}. Popraw symbol lub walutę.`);next.assets.find(x=>x.id===a.id).quote=H.quote({...a.quote,providerSymbol:a.quote?.providerSymbol||a.providerSymbol},q,a.providerSymbol);}catch(e){errors.push(a.symbol+': '+e.message);}}await commit(next);if(id&&modal.open)assetDetail(id);toast(errors.length?'Nie pobrano części kursów: '+errors.join('; '):'Pobrano notowania. Sprawdź datę przy każdej cenie.');}
 async function refreshNews(){if(demo)throw new Error('Otwórz swój portfel, aby pobrać aktualne wiadomości.');if(storageMode!=='server')throw new Error('Pobieranie kanałów RSS wymaga części PHP na serwerze.');const symbols=state.assets.filter(a=>a.providerSymbol).slice(0,10);news=[];const failures=[];for(const a of symbols){try{const result=await api('news&symbol='+encodeURIComponent(a.providerSymbol));news.push(...result.items.map(n=>({...n,symbol:a.symbol})));}catch(e){failures.push(a.symbol);}}newsLoaded=true;const seen=new Set();news=news.filter(n=>{if(seen.has(n.link))return false;seen.add(n.link);return true;}).sort((a,b)=>b.date.localeCompare(a.date));render();toast(failures.length?'Nie udało się pobrać kanałów: '+failures.join(', '):'Zaktualizowano wiadomości.');}
 function fileInput(accept,onFile){const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;if(file.size>8000000){toast('Plik jest zbyt duży (maks. 8 MB).');return;}try{await onFile(await file.text());}catch(e){toast(e.message);}});input.click();}
 function exportJSON(){const blob=new Blob([JSON.stringify({format:'stock-backup',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),link=document.createElement('a'),href=URL.createObjectURL(blob);link.href=href;link.download=`stock-${demo?'demo-':''}${C.today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Wyeksportowano kopię portfela.');}
